// Package httpapi is the API's HTTP edge. The router, the request decoding and
// the validation against the contract are generated by ogen into oas/; this
// package maps the generated types to the use cases and back, and every error
// to an RFC 9457 problem.
package httpapi

//go:generate go tool ogen --target oas --package oas --clean ../../../../../contracts/openapi.yaml

import (
	"context"
	"errors"
	"log/slog"
	"uuid"

	googleuuid "github.com/google/uuid"

	"github.com/christianchiavelli/spillway/services/api/internal/adapter/httpapi/oas"
	"github.com/christianchiavelli/spillway/services/api/internal/app/alerting"
	"github.com/christianchiavelli/spillway/services/api/internal/app/identity"
	"github.com/christianchiavelli/spillway/services/api/internal/domain/alert"
)

// Alerts is what the edge asks of the alerting use case. Declared here, by its
// consumer, so a handler test can stand in for it with a few lines.
type Alerts interface {
	Create(ctx context.Context, accountID uuid.UUID, d alert.Draft) (alert.Alert, error)
	List(ctx context.Context, accountID uuid.UUID) ([]alerting.Watched, error)
	Delete(ctx context.Context, accountID, alertID uuid.UUID) error
	Firings(ctx context.Context, accountID uuid.UUID, limit, offset int) (alerting.FiringPage, error)
}

// Identity is what the edge asks of the identity use case.
type Identity interface {
	SignUp(ctx context.Context, email, password string) (identity.Grant, error)
	SignIn(ctx context.Context, email, password string) (identity.Grant, error)
	SignOut(ctx context.Context, p identity.Principal) error
	Authenticate(ctx context.Context, token string) (identity.Principal, error)
}

// handler implements the generated oas.Handler and oas.SecurityHandler.
type handler struct {
	alerts   Alerts
	identity Identity
	reports  Reports
	logger   *slog.Logger
}

var (
	_ oas.Handler         = (*handler)(nil)
	_ oas.SecurityHandler = (*handler)(nil)
)

// errNoPrincipal means a secured operation ran without the security handler
// having put a principal in the context: a bug, answered with a 500.
var errNoPrincipal = errors.New("httpapi: no principal in the context of a secured operation")

type principalKey struct{}

// HandleSession reads the bearer token of every secured operation.
func (h *handler) HandleSession(ctx context.Context, _ oas.OperationName, t oas.Session) (context.Context, error) {
	p, err := h.identity.Authenticate(ctx, t.Token)
	if err != nil {
		return ctx, err
	}
	return context.WithValue(ctx, principalKey{}, p), nil
}

func principalFrom(ctx context.Context) (identity.Principal, error) {
	p, ok := ctx.Value(principalKey{}).(identity.Principal)
	if !ok {
		return identity.Principal{}, errNoPrincipal
	}
	return p, nil
}

func (h *handler) CreateAccount(ctx context.Context, req *oas.NewAccount) (*oas.SessionGrant, error) {
	g, err := h.identity.SignUp(ctx, string(req.Email), req.Password)
	if err != nil {
		return nil, err
	}
	return toSessionGrant(g), nil
}

func (h *handler) CreateSession(ctx context.Context, req *oas.Credentials) (*oas.SessionGrant, error) {
	g, err := h.identity.SignIn(ctx, string(req.Email), req.Password)
	if err != nil {
		return nil, err
	}
	return toSessionGrant(g), nil
}

func (h *handler) GetCurrentSession(ctx context.Context) (*oas.CurrentSession, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, err
	}
	return &oas.CurrentSession{
		ExpiresAt: p.ExpiresAt,
		Account:   oas.Account{ID: googleuuid.UUID(p.AccountID), Email: oas.Email(p.Email)},
	}, nil
}

func (h *handler) DeleteCurrentSession(ctx context.Context) error {
	p, err := principalFrom(ctx)
	if err != nil {
		return err
	}
	return h.identity.SignOut(ctx, p)
}

func (h *handler) ListAlerts(ctx context.Context) (*oas.AlertList, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, err
	}
	alerts, err := h.alerts.List(ctx, p.AccountID)
	if err != nil {
		return nil, err
	}
	items := make([]oas.WatchedAlert, len(alerts))
	for i, w := range alerts {
		a := toAlert(w.Alert)
		items[i] = oas.WatchedAlert{
			ID:           a.ID,
			Name:         a.Name,
			Source:       a.Source,
			Subsystem:    a.Subsystem,
			ThresholdMwh: a.ThresholdMwh,
			CreatedAt:    a.CreatedAt,
			LastFiredOn:  optDay(w.LastFiredOn),
			DaysFired:    int32(w.DaysFired), //nolint:gosec // at most alert.RecentDays
		}
	}
	return &oas.AlertList{Items: items}, nil
}

func (h *handler) ListFirings(ctx context.Context, params oas.ListFiringsParams) (*oas.FiringPage, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, err
	}
	page, err := h.alerts.Firings(ctx, p.AccountID, params.Limit.Or(10), params.Offset.Or(0))
	if err != nil {
		return nil, err
	}
	out := &oas.FiringPage{From: optDay(page.From), Through: optDay(page.Through), Total: page.Total, Items: make([]oas.Firing, len(page.Items))}
	for i, f := range page.Items {
		out.Items[i] = oas.Firing{
			AlertId:      googleuuid.UUID(f.AlertID),
			AlertName:    oas.AlertName(f.AlertName),
			Day:          oas.Day(f.Day),
			CurtailedMwh: oas.Energy(f.CurtailedMWh),
			ThresholdMwh: oas.Threshold(f.ThresholdMWh),
		}
	}
	return out, nil
}

func (h *handler) CreateAlert(ctx context.Context, req *oas.NewAlert) (*oas.Alert, error) {
	p, err := principalFrom(ctx)
	if err != nil {
		return nil, err
	}
	a, err := h.alerts.Create(ctx, p.AccountID, alert.Draft{
		Name:         string(req.Name),
		Source:       string(req.Source),
		Subsystem:    string(req.Subsystem),
		ThresholdMWh: int32(req.ThresholdMwh),
	})
	if err != nil {
		return nil, err
	}
	created := toAlert(a)
	return &created, nil
}

func (h *handler) DeleteAlert(ctx context.Context, params oas.DeleteAlertParams) error {
	p, err := principalFrom(ctx)
	if err != nil {
		return err
	}
	return h.alerts.Delete(ctx, p.AccountID, uuid.UUID(params.AlertId))
}

func toSessionGrant(g identity.Grant) *oas.SessionGrant {
	return &oas.SessionGrant{
		Token:     g.Token,
		ExpiresAt: g.Session.ExpiresAt.UTC(),
		Account:   oas.Account{ID: googleuuid.UUID(g.Account.ID), Email: oas.Email(g.Account.Email)},
	}
}

func toAlert(a alert.Alert) oas.Alert {
	return oas.Alert{
		ID:           googleuuid.UUID(a.ID),
		Name:         oas.AlertName(a.Name),
		Source:       oas.Source(a.Source),
		Subsystem:    oas.Subsystem(a.Subsystem),
		ThresholdMwh: oas.Threshold(a.ThresholdMWh),
		CreatedAt:    a.CreatedAt.UTC(),
	}
}
